  --skogo-red: #ff6666;
  --skogo-light-red: #a54447;
  --skogo-extra-light-red: #481d1e;
  --skogo-hinshi-mark: #cccccc;
  --skogo-shubetsu-mark: #cccccc;
  --skogo-gendai-mark: #cccccc;
}

.android .nightMode {
  --bg-color: black;
  --fg-color: white;
}

.android .nightMode:not(.ankidroid_dark_mode) {
  /* make it brighter since bg is black */
  --bg-elevated: rgba(255, 255, 255, 0.06);
}

.android .nightMode.ankidroid_dark_mode {
  --bg-color: #303030;
}

.card:not(.nightMode) {
  --bg-color: var(--light-mode-bg-color);
  --fg-color: var(--light-mode-fg-color);
  --heiban: var(--light-mode-heiban, initial);
  --atamadaka: var(--light-mode-atamadaka, initial);
  --nakadaka: var(--light-mode-nakadaka, initial);
  --odaka: var(--light-mode-odaka, initial);
  --kifuku: var(--light-mode-kifuku, initial);

  --bg-elevated: rgba(0, 0, 0, 0.03);
  --bg-inset: rgba(0, 0, 0, 0.06);
  --fg-subtle: rgba(0, 0, 0, 0.6);
  --bold: var(--light-mode-bold, #999999);

  --image-brightness: var(--light-mode-image-brightness);
  --tooltip-hover-color: var(--light-mode-tooltip-hover-color);

  /* Code for 大辞泉 二版 by kiwakiwaa
    and can be found here https://github.com/kiwakiwaa/vertical-cards?tab=readme-ov-file#my-yomitan-dictionaries */
  --daijisen-black: #ffffff;
  --daijisen-white: #000000;
  --daijisen-blue: #00aaff;
  --daijisen-header-djs: #a0484f;
  --daijisen-header-djsp: #7a7a7a;
  --daijisen-header-text: #000000;
  --daijisen-logo-color: #dddddd;
  --daijisen-background-l3: #c0c0c0;
  --daijisen-accent-mark: #ff6666;
  --daijisen-accent-slash: #a0a0a0;

  --ozk5-blue: #4a8ade;
  --ozk5-red: #c00000;
  --ozk5-light-red: #d96666;
  --ozk5-gray: #888;
  --ozk5-hinshi-mark: #444;
  --ozk5-kakomi-border: #999;
  --ozk5-metadata-background: #999;
  --ozk5-example-katsuyou-mark: #666;
  --ozk5-mark-border: #660;
  --ozk5-gogi-panel-header: #f9e6e6;
  --ozk5-ruigo-panel-background: #444;
  --ozk5-ruigo-panel-border: #aaa;
  --ozk5-appendix-title-background: #633;
  --ozk5-gendai-mark: #888;
  /* --background-color: #f5f5f5; */

  --skogo-blue: #4a8ade;
  --skogo-red: #c00000;
  --skogo-light-red: #dfa6a8;
  --skogo-extra-light-red: #ffeeee;
  --skogo-hinshi-mark: #444;
  --skogo-shubetsu-mark: #707070;
  --skogo-gendai-mark: #888;
}

html {
  --main-font-size: var(--pc-main-font-size);
  --main-def-size: var(--pc-main-def-size);
  --vocab-font-size: var(--pc-vocab-font-size);
  --back-vocab-font-size: var(--pc-back-vocab-font-size);
  --sentence-font-size: var(--pc-sentence-font-size);
  --back-sentence-font-size: var(--pc-back-sentence-font-size);
  --hint-font-size: var(--pc-hint-font-size);
  --info-font-size: var(--pc-info-font-size);
}

html.mobile {
  --main-font-size: var(--mobile-main-font-size);
  --main-def-size: var(--mobile-main-def-size);
  --vocab-font-size: var(--mobile-vocab-font-size);
  --back-vocab-font-size: var(--mobile-back-vocab-font-size);
  --sentence-font-size: var(--mobile-sentence-font-size);
  --back-sentence-font-size: var(--mobile-back-sentence-font-size);
  --hint-font-size: var(--mobile-hint-font-size);
  --info-font-size: var(--mobile-info-font-size);
  --main-picture-position: var(--mobile-main-picture-position);
  --sentence-position: var(--mobile-sentence-position);
  --audio-buttons: var(--mobile-audio-buttons);
}

#lapis {
  display: flex;
  align-items: stretch;
  flex-direction: column;
  min-height: calc(100vh - 40px);
  font-family: var(--font-serif);
  font-size: var(--main-font-size);
  text-align: center;
}

/* ------- Mobile css ------- */
@media (max-width: 512px) {
  .images-container {
    justify-content: space-around;
    flex-direction: row !important;
    max-width: 100% !important;
    width: 100%;
    flex-wrap: wrap;
  }

  .images-container img {
    width: 44%;
  }

  .img-popup-container {
    max-width: 100vw;
    max-height: 60vh;
  }

  .img-popup-img {
    object-fit: contain;
  }
}

@media (min-width: 768px) and (max-width: 1024px) {
  .img-popup-container {
    max-height: 70vh;
  }

  .img-popup-img {
    object-fit: contain;
  }
}

/* ----- Front elements ----- */

.front-vocab {
  font-size: var(--vocab-font-size);
  line-height: 1.5;
}

.front-sentence {
  font-size: var(--sentence-font-size);
  display: inline-block;
  line-height: 1.5;
}

#hint {
  font-size: var(--hint-font-size);
  margin-top: -5px;
  line-height: 1.5;
}

#click {
  user-select: none;
}

#click .front-vocab {
  display: inline-block;
  line-height: 1.2;
  margin-bottom: 20px;
  border-bottom: 2px dotted var(--fg-subtle);
}

/* ----- Back elements ----- */

/* Vocab on the back (for mobile) */
.vocab {
  line-height: 1.5;
  font-size: var(--back-vocab-font-size);
}

a {
  color: #3b82f6 !important;
}

.nightMode a {
  color: #93c5fd !important;
}

/* Header */
header {
  color: var(--fg-subtle);
  height: 40px;
  text-align: right;
  width: 100%;
  font-size: 1rem;
}

.top-container {
  font-family: var(--font-sans);
  max-width: calc(var(--max-width) + 20px);
  margin: 0px auto;
  width: calc(100% - 20px);
  fill: var(--fg-subtle) !important;
  position: relative;
  display: inline-block;
}

.freq-dropdown {
  cursor: pointer;
}

.freq-list-container {
  display: none;
  position: absolute;
  top: 100%;
  right: 0;
  background-color: var(--tooltip-hover-color);
  color: var(--fg-color);
  padding: 10px;
  border-radius: 5px;
  z-index: 1000;
  width: 200px;
}

.freq-list-container ul {
  list-style-type: none;
  line-height: 1.5;
  margin: 0;
  padding: 0;
}

.freq-dropdown:hover .freq-list-container {
  display: block;
}

main {
  width: min(var(--max-width), calc(100% - 20px));
  margin-inline: auto;
}

/* Info (audio, reading) */
.info {
  font-family: var(--font-sans);
  font-size: var(--info-font-size, 0.9rem);
  color: var(--fg-color);
}

.mobile .info {
  padding-top: 7px;
}

/* Replay button */
.replay-button svg {
  width: 32px;
  height: 32px;
}

.mobile .audio-buttons {
  position: fixed;
  bottom: 0;
  left: 0;
  z-index: 1000;
}

.audio-buttons-alt {
    font-size: 0;
}

/* Pitch */
.pitch {
  display: inline;
}

#pitch-tags {
  background-color: var(--fg-color);
  color: var(--bg-color);
  font-family: var(--font-sans);
  font-weight: 500;
  display: none;
  vertical-align: top;
  padding: 1px 3px;
  margin-right: -5px;
  &:has(li) {
    display: inline-block;
  }
}

.mobile .nightMode #pitch-tags {
  color: #000 !important;
  background-color: #fff;
}

/* When multiple pitch */
.pitch ul,
#pitch-tags ul {
  list-style: none;
  display: inline;
  margin: 0;
  padding: 0;
}

.pitch li,
#pitch-tags li {
  display: inline;
}

.pitch ul > li:not(:last-child)::after {
  content: "・";
  color: var(--fg-color);
}

#pitch-tags ul > li:not(:last-child)::after {
  content: "・";
  color: var(--bg-color);
  font-size: 0.8em;
}

/* Definition container */
.main-def {
  background-color: var(--bg-elevated);
  font-family: var(--font-sans);
  font-size: var(--main-def-size);
  line-height: 1.75em;
  text-align: left;
  border-left: 5px solid #ccc;
  padding: 0.5em 10px;
  margin: 5px auto 10px auto;
  overflow: hidden;
  position: relative;
}

.main-def ol {
  margin-block: 0em;
}

/* Definition info display */
.def-info {
  font-family: var(--font-sans);
  color: var(--fg-subtle);
  font-size: 0.9rem;
  text-align: right;
  pointer-events: none;
  visibility: hidden;
}

.mobile .def-info {
  margin-bottom: -5px;
}

/* MainDefinition */
.definition {
  text-align: left;
  width: fit-content;
  max-width: 100%;
}

/* Definition toggle css */
.edge {
  position: absolute;
  top: 0;
  width: 50px;
  height: 100%;
  cursor: pointer;
  opacity: 0.4;
}

.edge:hover {
  background-color: var(--bg-inset);
}

#edge-prev {
  left: 0;
  border-radius: 8px 0px 0px 8px;
}

#edge-next {
  right: 0;
  border-radius: 0px 8px 8px 0px;
}

/* Hide edges when not needed */
.edge:has(~ .definition > :last-child:first-child) {
  display: none;
}

/* Primary Image */
.image img, .image-alt img {
  max-height: 400px;
  width: auto;
  border-radius: 5px;
  cursor: pointer;
  transition: filter 0.3s;
}

.image-alt img {
  margin: auto;
  max-width: 60%;
  max-height: 250px;
  border: solid var(--fg-subtle) 2px;
  font-size: 0;
}

.image img:hover,
.image-alt img:hover,
.def-image img:hover {
  filter: brightness(var(--image-brightness));
}

/* Definition Image(s) */
.def-image {
  float: right;
  margin-left: 10px;
  max-width: min(35%, var(--def-picture-size));
  display: flex;
  flex-flow: column nowrap;
  justify-content: flex-start;
  gap: 10px;
}

.def-image img {
  object-fit: contain;
  max-height: var(--def-picture-size);
  border-radius: 3px;
  cursor: pointer;
  transition: filter 0.3s;
}

.def-image ol {
  list-style-type: none;
  padding: 0;
  margin: 0;
}

/* Image modal css */
.modal-bg {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  background-color: rgba(0, 0, 0, 0.8);
  z-index: 1000;
  cursor: pointer;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity 0.3s ease,
    visibility 0.3s ease;
}

.modal-bg.active {
  opacity: 1;
  visibility: visible;
}

.img-popup-container {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(calc(100% - 20px), calc(var(--max-width) + 200px));
  z-index: 1001;
  overflow: hidden;
  display: flex;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity 0.3s ease,
    visibility 0.3s ease;
}

.img-popup-container.active {
  opacity: 1;
  visibility: visible;
}

.img-popup-img {
  width: auto;
  height: auto;
  margin: 0 auto;
  transition: transform 0.3s ease;
}

/* Hide NFSW Images -- make sure you use the tag `NSFW` EXACTLY */
.NSFW img,
.nsfw img,
.Nsfw img {
  filter: blur(30px);
  transition: filter 0.2s;

  &:hover {
    filter: blur(0px);
  }
}

/* Back sentence */
.sentence,
.sentence-alt {
  line-height: 1.5;
  font-size: var(--back-sentence-font-size);
  display: inline-block;

  /* show furigana on hover */
  & rt {
    visibility: hidden;
  }

  & ruby:hover rt {
    visibility: visible;
  }
}

/* Footer */
footer {
  margin-top: auto;
  width: 100%;
}

.bot-container {
  display: flex;
  justify-content: flex-end;
  max-width: calc(var(--max-width) + 20px);
  margin: 0px auto;
  width: calc(100% - 20px);
}

.tags-container {
  flex-grow: 1;
}

.tags-container .tags {
  min-height: 1.6em;
}

.tags {
  font-family: var(--font-sans);
  background-color: var(--bg-elevated);
  color: var(--fg-color);
  display: inline-grid;
  place-items: center;
  padding: 1px 5px;
  cursor: pointer;
  border-radius: 5px;
  font-size: 0.9rem;
  margin: auto 3px;
  text-overflow: ellipsis;
  overflow: hidden;
  max-width: 60dvw;
  white-space: nowrap;
}

.mobile .tags {
  padding: 1px 3px;
  font-size: 9px;
}

/* Definition Header */
.def-header {
  display: flex;
  font-size: 30px;
  justify-content: center;
  align-items: center;
  max-width: 820px;
  margin-inline: auto;
  position: relative;
  gap: min(20px, 2vw);
}

.dh-vocab {
  background: var(--bg-elevated);
  padding: 0.52em;
  border-radius: 5px;
  flex: 1;
  /* takes up all available space */
}

.dh-image {
  max-width: 400px;
  position: relative;
  font-size: 0;
  /* weird hack needed to make the image stay in line with the .def-header */
}

.mobile .dh-vocab {
  background: none;
  padding: 0em;
  border-radius: 0px;
}

.mobile .dh-vocab:has(~ .dh-image) {
  max-width: 60vw;
}

.mobile .dh-image {
  max-width: 40vw;
}

/* Misc. info */
.misc-info {
  font-family: var(--font-sans);
  background-color: var(--bg-elevated);
  border-radius: 8px;
  padding: 10px;
  margin: 0 auto;
}

.misc-info ul {
  margin: 0;
}

/* ----- Misc ----- */

/* Furigana */
ruby rt {
  user-select: none;
}

/* Bold */
b {
  color: var(--bold);
  font-weight: 600;
}

.mobile b {
  font-weight: 400;
}

/* Hide scrollbar */
.card {
  -ms-overflow-style: none;
  scrollbar-width: 0;

  &::-webkit-scrollbar {
    display: none;
  }
}

/* Dropdown */
details {
  font-family: var(--font-sans);
  margin: 5px 0px;
}

summary {
  user-select: none;
  cursor: pointer;
  margin: 0px auto;
}

/* Pitch overline */
.pitch-item>span {
    position: relative;
    white-space: nowrap;
}

.pitch-line {
    display: block;
    position: absolute;
    top: -0.1em;
    left: 0;
    right: 0;
    border-width: 0.1em;
    border-top-style: solid;
}

.pitch-low>.pitch-line {
    border-top-style: none;
}

.pitch-to-drop {
    padding-right: 0.1em;
    margin-right: 0.1em;
    &>.pitch-line {
        height: 0.4em;
        right: -0.1em;
        border-right-style: solid;
    }
}

/* Pitch coloring */
.heiban {
  color: var(--heiban);
}

.atamadaka {
  color: var(--atamadaka);
}

.nakadaka {
  color: var(--nakadaka);
}

.odaka {
  color: var(--odaka);
}

.kifuku {
  color: var(--kifuku);
}

/* Format Definitions */
ul[data-sc-content="glossary"],
[data-sc-content="forms"] ul,
[data-dictionary^="JMdict"] ul:not([data-sc-content]) {
    display: inline;
    list-style: none;
    padding-left: 0!important;

    &>li:not(:first-child)::before {
        white-space: pre-wrap;
        content: " | ";
        display: inline;
    }

    & > li {
        display: inline;
    }
}

[data-sc-content="glossary"] ~ ul,
[data-sc-content="glossary"] ~ div {
