  color: var(--fg-color);
}

#pitch-tags ul > li:not(:last-child)::after {
  content: "・";
  color: var(--bg-color);
  font-size: 0.8em;
}

/* Definition container */
.main-def {
  background-color: var(--bg-elevated);
  font-family: var(--font-sans);
  font-size: var(--main-def-size);
  line-height: 1.75em;
  text-align: left;
  border-left: 5px solid #ccc;
  padding: 0.5em 10px;
  margin: 5px auto 10px auto;
  overflow: hidden;
  position: relative;
}

.main-def ol {
  margin-block: 0em;
}

/* Definition info display */
.def-info {
  font-family: var(--font-sans);
  color: var(--fg-subtle);
  font-size: 0.9rem;
  text-align: right;
  pointer-events: none;
  visibility: hidden;
}

.mobile .def-info {
  margin-bottom: -5px;
}

/* MainDefinition */
.definition {
  text-align: left;
  width: fit-content;
  max-width: 100%;
}

/* Definition toggle css */
.edge {
  position: absolute;
  top: 0;
  width: 50px;
  height: 100%;
  cursor: pointer;
  opacity: 0.4;
}

.edge:hover {
  background-color: var(--bg-inset);
}

#edge-prev {
  left: 0;
  border-radius: 8px 0px 0px 8px;
}

#edge-next {
  right: 0;
  border-radius: 0px 8px 8px 0px;
}

/* Hide edges when not needed */
.edge:has(~ .definition > :last-child:first-child) {
  display: none;
}

/* Primary Image */
.image img, .image-alt img {
  max-height: 400px;
  width: auto;
  border-radius: 5px;
  cursor: pointer;
  transition: filter 0.3s;
}

.image-alt img {
  margin: auto;
  max-width: 60%;
  max-height: 250px;
  border: solid var(--fg-subtle) 2px;
  font-size: 0;
}

.image img:hover,
.image-alt img:hover,
.def-image img:hover {
  filter: brightness(var(--image-brightness));
}

/* Definition Image(s) */
.def-image {
  float: right;
  margin-left: 10px;
  max-width: min(35%, var(--def-picture-size));
  display: flex;
  flex-flow: column nowrap;
  justify-content: flex-start;
  gap: 10px;
}

.def-image img {
  object-fit: contain;
  max-height: var(--def-picture-size);
  border-radius: 3px;
  cursor: pointer;
  transition: filter 0.3s;
}

.def-image ol {
  list-style-type: none;
  padding: 0;
  margin: 0;
}

/* Image modal css */
.modal-bg {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  background-color: rgba(0, 0, 0, 0.8);
  z-index: 1000;
  cursor: pointer;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity 0.3s ease,
    visibility 0.3s ease;
}

.modal-bg.active {
  opacity: 1;
  visibility: visible;
}

.img-popup-container {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(calc(100% - 20px), calc(var(--max-width) + 200px));
  z-index: 1001;
  overflow: hidden;
  display: flex;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity 0.3s ease,
    visibility 0.3s ease;
}

.img-popup-container.active {
  opacity: 1;
  visibility: visible;
}

.img-popup-img {
  width: auto;
  height: auto;
  margin: 0 auto;
  transition: transform 0.3s ease;
}

/* Hide NFSW Images -- make sure you use the tag `NSFW` EXACTLY */
.NSFW img,
.nsfw img,
.Nsfw img {
  filter: blur(30px);
  transition: filter 0.2s;

  &:hover {
    filter: blur(0px);
  }
}

/* Back sentence */
.sentence,
.sentence-alt {
  line-height: 1.5;
  font-size: var(--back-sentence-font-size);
  display: inline-block;

  /* show furigana on hover */
  & rt {
    visibility: hidden;
  }

  & ruby:hover rt {
    visibility: visible;
  }
}

/* Footer */
footer {
  margin-top: auto;
  width: 100%;
}

.bot-container {
  display: flex;
  justify-content: flex-end;
  max-width: calc(var(--max-width) + 20px);
  margin: 0px auto;
  width: calc(100% - 20px);
}

.tags-container {
  flex-grow: 1;
}

.tags-container .tags {
  min-height: 1.6em;
}

.tags {
  font-family: var(--font-sans);
  background-color: var(--bg-elevated);
  color: var(--fg-color);
  display: inline-grid;
  place-items: center;
  padding: 1px 5px;
  cursor: pointer;
  border-radius: 5px;
  font-size: 0.9rem;
  margin: auto 3px;
  text-overflow: ellipsis;
  overflow: hidden;
  max-width: 60dvw;
  white-space: nowrap;
}

.mobile .tags {
  padding: 1px 3px;
  font-size: 9px;
}

/* Definition Header */
.def-header {
  display: flex;
  font-size: 30px;
  justify-content: center;
  align-items: center;
  max-width: 820px;
  margin-inline: auto;
  position: relative;
  gap: min(20px, 2vw);
}

.dh-vocab {
  background: var(--bg-elevated);
  padding: 0.52em;
  border-radius: 5px;
  flex: 1;
  /* takes up all available space */
}

.dh-image {
  max-width: 400px;
  position: relative;
  font-size: 0;
