  --main-picture-position: var(--mobile-main-picture-position);
  --sentence-position: var(--mobile-sentence-position);
  --audio-buttons: var(--mobile-audio-buttons);
}

#lapis {
  display: flex;
  align-items: stretch;
  flex-direction: column;
  min-height: calc(100vh - 40px);
  font-family: var(--font-serif);
  font-size: var(--main-font-size);
  text-align: center;
}

/* ------- Mobile css ------- */
@media (max-width: 512px) {
  .images-container {
    justify-content: space-around;
    flex-direction: row !important;
    max-width: 100% !important;
    width: 100%;
    flex-wrap: wrap;
  }

  .images-container img {
    width: 44%;
  }

  .img-popup-container {
    max-width: 100vw;
    max-height: 60vh;
  }

  .img-popup-img {
    object-fit: contain;
  }
}

@media (min-width: 768px) and (max-width: 1024px) {
  .img-popup-container {
    max-height: 70vh;
  }

  .img-popup-img {
    object-fit: contain;
  }
}

/* ----- Front elements ----- */

.front-vocab {
  font-size: var(--vocab-font-size);
  line-height: 1.5;
}

.front-sentence {
  font-size: var(--sentence-font-size);
  display: inline-block;
  line-height: 1.5;
}

#hint {
  font-size: var(--hint-font-size);
  margin-top: -5px;
  line-height: 1.5;
}

#click {
  user-select: none;
}

#click .front-vocab {
  display: inline-block;
  line-height: 1.2;
  margin-bottom: 20px;
  border-bottom: 2px dotted var(--fg-subtle);
}

/* ----- Back elements ----- */

/* Vocab on the back (for mobile) */
.vocab {
  line-height: 1.5;
  font-size: var(--back-vocab-font-size);
}

a {
  color: #3b82f6 !important;
}

.nightMode a {
  color: #93c5fd !important;
}

/* Header */
header {
  color: var(--fg-subtle);
  height: 40px;
  text-align: right;
  width: 100%;
  font-size: 1rem;
}

.top-container {
  font-family: var(--font-sans);
  max-width: calc(var(--max-width) + 20px);
  margin: 0px auto;
  width: calc(100% - 20px);
  fill: var(--fg-subtle) !important;
  position: relative;
  display: inline-block;
}

.freq-dropdown {
  cursor: pointer;
}

.freq-list-container {
  display: none;
  position: absolute;
  top: 100%;
  right: 0;
  background-color: var(--tooltip-hover-color);
  color: var(--fg-color);
  padding: 10px;
  border-radius: 5px;
  z-index: 1000;
  width: 200px;
}

.freq-list-container ul {
  list-style-type: none;
  line-height: 1.5;
  margin: 0;
  padding: 0;
}

.freq-dropdown:hover .freq-list-container {
  display: block;
}

main {
  width: min(var(--max-width), calc(100% - 20px));
  margin-inline: auto;
}

/* Info (audio, reading) */
.info {
  font-family: var(--font-sans);
  font-size: var(--info-font-size, 0.9rem);
  color: var(--fg-color);
}

.mobile .info {
  padding-top: 7px;
}

/* Replay button */
.replay-button svg {
  width: 32px;
  height: 32px;
}

.mobile .audio-buttons {
  position: fixed;
  bottom: 0;
  left: 0;
  z-index: 1000;
}

.audio-buttons-alt {
    font-size: 0;
}

/* Pitch */
.pitch {
  display: inline;
}

#pitch-tags {
  background-color: var(--fg-color);
  color: var(--bg-color);
  font-family: var(--font-sans);
  font-weight: 500;
  display: none;
  vertical-align: top;
  padding: 1px 3px;
  margin-right: -5px;
  &:has(li) {
    display: inline-block;
  }
}

.mobile .nightMode #pitch-tags {
  color: #000 !important;
  background-color: #fff;
}

/* When multiple pitch */
.pitch ul,
#pitch-tags ul {
  list-style: none;
  display: inline;
  margin: 0;
  padding: 0;
}

.pitch li,
#pitch-tags li {
  display: inline;
}

.pitch ul > li:not(:last-child)::after {
  content: "・";
  color: var(--fg-color);
}

#pitch-tags ul > li:not(:last-child)::after {
  content: "・";
  color: var(--bg-color);
  font-size: 0.8em;
}

/* Definition container */
.main-def {
  background-color: var(--bg-elevated);
  font-family: var(--font-sans);
  font-size: var(--main-def-size);
  line-height: 1.75em;
  text-align: left;
  border-left: 5px solid #ccc;
  padding: 0.5em 10px;
  margin: 5px auto 10px auto;
  overflow: hidden;
  position: relative;
}

.main-def ol {
  margin-block: 0em;
}

/* Definition info display */
.def-info {
  font-family: var(--font-sans);
  color: var(--fg-subtle);
  font-size: 0.9rem;
  text-align: right;
  pointer-events: none;
  visibility: hidden;
}

.mobile .def-info {
  margin-bottom: -5px;
}

/* MainDefinition */
.definition {
  text-align: left;
  width: fit-content;
  max-width: 100%;
}

/* Definition toggle css */
.edge {
  position: absolute;
  top: 0;
  width: 50px;
  height: 100%;
  cursor: pointer;
  opacity: 0.4;
}

.edge:hover {
  background-color: var(--bg-inset);
}

#edge-prev {
  left: 0;
  border-radius: 8px 0px 0px 8px;
}

#edge-next {
  right: 0;
  border-radius: 0px 8px 8px 0px;
}

/* Hide edges when not needed */
.edge:has(~ .definition > :last-child:first-child) {
  display: none;
}

/* Primary Image */
.image img, .image-alt img {
  max-height: 400px;
  width: auto;
  border-radius: 5px;
  cursor: pointer;
  transition: filter 0.3s;
}

.image-alt img {
  margin: auto;
  max-width: 60%;
  max-height: 250px;
  border: solid var(--fg-subtle) 2px;
  font-size: 0;
}

.image img:hover,
.image-alt img:hover,
.def-image img:hover {
  filter: brightness(var(--image-brightness));
}

/* Definition Image(s) */
.def-image {
  float: right;
  margin-left: 10px;
  max-width: min(35%, var(--def-picture-size));
  display: flex;
  flex-flow: column nowrap;
  justify-content: flex-start;
  gap: 10px;
}

.def-image img {
  object-fit: contain;
  max-height: var(--def-picture-size);
  border-radius: 3px;
  cursor: pointer;
  transition: filter 0.3s;
}

.def-image ol {
  list-style-type: none;
  padding: 0;
  margin: 0;
}

/* Image modal css */
.modal-bg {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  background-color: rgba(0, 0, 0, 0.8);
  z-index: 1000;
  cursor: pointer;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity 0.3s ease,
    visibility 0.3s ease;
}

.modal-bg.active {
  opacity: 1;
  visibility: visible;
}

.img-popup-container {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(calc(100% - 20px), calc(var(--max-width) + 200px));
  z-index: 1001;
  overflow: hidden;
  display: flex;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity 0.3s ease,
    visibility 0.3s ease;
}

.img-popup-container.active {
  opacity: 1;
  visibility: visible;
}

.img-popup-img {
  width: auto;
  height: auto;
  margin: 0 auto;
  transition: transform 0.3s ease;
}

/* Hide NFSW Images -- make sure you use the tag `NSFW` EXACTLY */
.NSFW img,
.nsfw img,
.Nsfw img {
  filter: blur(30px);
  transition: filter 0.2s;

  &:hover {
    filter: blur(0px);
  }
}

/* Back sentence */
.sentence,
.sentence-alt {
  line-height: 1.5;
  font-size: var(--back-sentence-font-size);
  display: inline-block;

  /* show furigana on hover */
  & rt {
    visibility: hidden;
  }

  & ruby:hover rt {
    visibility: visible;
  }
}

/* Footer */
footer {
  margin-top: auto;
  width: 100%;
}

.bot-container {
  display: flex;
  justify-content: flex-end;
  max-width: calc(var(--max-width) + 20px);
  margin: 0px auto;
  width: calc(100% - 20px);
}

.tags-container {
  flex-grow: 1;
}

.tags-container .tags {
  min-height: 1.6em;
}

.tags {
  font-family: var(--font-sans);
  background-color: var(--bg-elevated);
  color: var(--fg-color);
  display: inline-grid;
  place-items: center;
  padding: 1px 5px;
  cursor: pointer;
  border-radius: 5px;
  font-size: 0.9rem;
  margin: auto 3px;
  text-overflow: ellipsis;
  overflow: hidden;
  max-width: 60dvw;
  white-space: nowrap;
}

.mobile .tags {
  padding: 1px 3px;
  font-size: 9px;
}

/* Definition Header */
.def-header {
  display: flex;
  font-size: 30px;
  justify-content: center;
  align-items: center;
  max-width: 820px;
  margin-inline: auto;
  position: relative;
  gap: min(20px, 2vw);
}

.dh-vocab {
  background: var(--bg-elevated);
  padding: 0.52em;
  border-radius: 5px;
  flex: 1;
  /* takes up all available space */
}

.dh-image {
  max-width: 400px;
  position: relative;
  font-size: 0;
  /* weird hack needed to make the image stay in line with the .def-header */
}

.mobile .dh-vocab {
  background: none;
  padding: 0em;
  border-radius: 0px;
}

.mobile .dh-vocab:has(~ .dh-image) {
  max-width: 60vw;
}

.mobile .dh-image {
  max-width: 40vw;
}

/* Misc. info */
.misc-info {
  font-family: var(--font-sans);
  background-color: var(--bg-elevated);
  border-radius: 8px;
  padding: 10px;
  margin: 0 auto;
}

.misc-info ul {
  margin: 0;
}

/* ----- Misc ----- */

/* Furigana */
ruby rt {
  user-select: none;
}

/* Bold */
b {
  color: var(--bold);
  font-weight: 600;
}

.mobile b {
  font-weight: 400;
}

/* Hide scrollbar */
.card {
  -ms-overflow-style: none;
  scrollbar-width: 0;

  &::-webkit-scrollbar {
    display: none;
  }
}

/* Dropdown */
details {
  font-family: var(--font-sans);
  margin: 5px 0px;
}

summary {
  user-select: none;
  cursor: pointer;
  margin: 0px auto;
}

/* Pitch overline */
.pitch-item>span {
    position: relative;
    white-space: nowrap;
}

.pitch-line {
    display: block;
    position: absolute;
    top: -0.1em;
    left: 0;
    right: 0;
    border-width: 0.1em;
    border-top-style: solid;
}

.pitch-low>.pitch-line {
    border-top-style: none;
}

.pitch-to-drop {
    padding-right: 0.1em;
    margin-right: 0.1em;
    &>.pitch-line {
        height: 0.4em;
        right: -0.1em;
        border-right-style: solid;
    }
}

/* Pitch coloring */
.heiban {
  color: var(--heiban);
}

.atamadaka {
  color: var(--atamadaka);
}

.nakadaka {
  color: var(--nakadaka);
}

.odaka {
  color: var(--odaka);
}

.kifuku {
  color: var(--kifuku);
}

/* Format Definitions */
ul[data-sc-content="glossary"],
[data-sc-content="forms"] ul,
[data-dictionary^="JMdict"] ul:not([data-sc-content]) {
    display: inline;
    list-style: none;
    padding-left: 0!important;

    &>li:not(:first-child)::before {
        white-space: pre-wrap;
        content: " | ";
        display: inline;
    }

    & > li {
        display: inline;
    }
}

[data-sc-content="glossary"] ~ ul,
[data-sc-content="glossary"] ~ div {
  line-height: normal;
}

[data-sc-content="attribution"],
[data-sc-content="graphic-attribution"] {
  display: none;
}

/* reduce indentations of Jitendex for mobile */
.mobile li[data-dictionary^="Jitendex"] ul,
.mobile li[data-dictionary^="Jitendex"] ol,
.mobile li[data-details^="Jitendex"] ul,
.mobile li[data-details^="Jitendex"] ol {
  padding-left: 0.3em;
}

/* Turn off italics */
.definition i {
  font-style: normal;
}

li[data-dictionary^="JMdict"] i {
  font-style: italic;
}

.definition a span {
  max-width: 300px !important;
}

.definition .hidden {
  display: none;
}

/* Prevent wrapping in the middle of a Jitendex tags */
span[data-sc-code] {
  white-space: nowrap;
}

/* backwards compatibility code for JPMN definitions */
li[data-details="JMdict (English)"] .dict-group__glossary > ul,
li[data-details="JMdict (English)"]
  .dict-group__glossary
  ul[data-sc-content="glossary"],
li[data-details="JMdict"] .dict-group__glossary > ul,
li[data-details="JMdict"] .dict-group__glossary ul[data-sc-content="glossary"],
li[data-details="JMdict Extra"] .dict-group__glossary > ul,
li[data-details="JMdict Extra"]
  .dict-group__glossary
  ul[data-sc-content="glossary"] {
  display: inline;
  padding-left: 0em;
}

li[data-details="JMdict (English)"] .dict-group__glossary > ul > li,
li[data-details="JMdict (English)"]
  .dict-group__glossary
  ul[data-sc-content="glossary"]
  > li,
li[data-details="JMdict"] .dict-group__glossary > ul > li,
li[data-details="JMdict"]
  .dict-group__glossary
  ul[data-sc-content="glossary"]
  > li,
li[data-details="JMdict Extra"] .dict-group__glossary > ul > li,
li[data-details="JMdict Extra"]
  .dict-group__glossary
  ul[data-sc-content="glossary"]
  > li {
  display: inline;
  padding-right: 0em;
  margin-right: 0em;
}

li[data-details="JMdict (English)"] .dict-group__glossary > ul > li::after,
li[data-details="JMdict (English)"]
  .dict-group__glossary
  ul[data-sc-content="glossary"]
  > li::after,
li[data-details="JMdict"] .dict-group__glossary > ul > li::after,
li[data-details="JMdict"]
  .dict-group__glossary
  ul[data-sc-content="glossary"]
  > li::after,
li[data-details="JMdict Extra"] .dict-group__glossary > ul > li::after,
li[data-details="JMdict Extra"]
  .dict-group__glossary
  ul[data-sc-content="glossary"]
  > li::after {
  content: " | ";
  white-space: pre-wrap;
}

li[data-details="JMdict (English)"]
  .dict-group__glossary
  > ul
  > li:last-of-type:after,
li[data-details="JMdict (English)"]
  .dict-group__glossary
  ul[data-sc-content="glossary"]
  > li:last-of-type:after,
li[data-details="JMdict"] .dict-group__glossary > ul > li:last-of-type:after,
li[data-details="JMdict"]
  .dict-group__glossary
  ul[data-sc-content="glossary"]
  > li:last-of-type:after,
li[data-details="JMdict Extra"]
  .dict-group__glossary
  > ul
  > li:last-of-type:after,
li[data-details="JMdict Extra"]
  .dict-group__glossary
  ul[data-sc-content="glossary"]
  > li:last-of-type:after {
  display: none;
}

/*
 * customization for specific dictionaries
 */
/* Makes JMdict italic */
ol li[data-details="JMdict (English)"] .dict-group__tag-list,
ol li[data-details="JMdict"] .dict-group__tag-list,
ol li[data-details="JMdict Extra"] .dict-group__tag-list {
  font-style: italic;
}

/* removes the dictionary entry for jmdict */
ol
  li[data-details="JMdict (English)"]
  .dict-group__tag-list
  .dict-group__tag--dict,
ol li[data-details="JMdict"] .dict-group__tag-list .dict-group__tag--dict,
ol
  li[data-details="JMdict Extra"]
  .dict-group__tag-list
  .dict-group__tag--dict {
  display: none;
}

/* Makes Nico/Pixiv italic */
ol li[data-details="Nico/Pixiv"] .dict-group__tag-list {
  font-style: italic;
}

/* Removes the extra text for the collapsed 新和英 display */
ol
  li[data-details="新和英"]
  details.glossary-text__details
  .glossary-text__summary
  .dict-group__glossary--first-line {
  display: none;
}

/*
 * --------------------
 *  dictionary entries
 * --------------------
 */
.dict-group__tag-list .dict-group__tag:not(:first-child)::before {
  content: ", ";
}

.dict-group__tag-list::before {
  content: "(";
}

.dict-group__tag-list::after {
  content: ") ";
}

.definition ol:has(> li[data-dictionary]),
.definition ol:has(> li[data-details]) {
  padding-inline-start: 1.3em;
}

/* Removes list numbering when only one list element  */
.definition ol:has(> li[data-dictionary]:only-of-type),
.definition ol:has(> li[data-details]:only-of-type) {
  list-style-type: none;
  padding-inline-start: 0;
}

/* Better formatting meikyo 3rd edition */
li[data-dictionary="明鏡国語辞典 第三版"] span {
  width: 25em !important;
  vertical-align: bottom !important;
}

li[data-dictionary="明鏡国語辞典 第三版"]
  div:has(> span[data-sc-class="品格"]) {
  margin-bottom: 5px !important;
}

li[data-dictionary="明鏡国語辞典 第三版"] [data-sc-body] {
  font-size: var(--main-def-size) !important;
}

/* Formatting for sanseido kogo dict */
li[data-dictionary="三省堂 全訳読解古語辞典"] span[data-sc-body] {
  line-height: 1.4em;
}
[data-dictionary="三省堂 全訳読解古語辞典"] span[data-sc-rectr][data-sc-fill] {
  color: #f5f5f5 !important;
}
.nightMode
  [data-dictionary="三省堂 全訳読解古語辞典"]
  span[data-sc-rectr][data-sc-fill] {
  color: #1e1e1e !important;
}

/* Formatting for oubunsha kogo dict */
li[data-dictionary="旺文社 全訳古語辞典"] [data-sc-audio_play_button],
li[data-dictionary="旺文社 全訳古語辞典"] [data-sc-audio_stop_button] {
  display: none !important;
}
li[data-dictionary="旺文社 全訳古語辞典"] div[data-sc用例囲み-g],
li[data-dictionary="旺文社 全訳古語辞典"] div[data-sc和歌俳句囲み-g],
li[data-dictionary="旺文社 全訳古語辞典"] div[data-sc冒頭文囲み-g],
li[data-dictionary="旺文社 全訳古語辞典"] div[data-sc小倉囲み-g] {
  margin-top: 0 !important;
}
[data-dictionary="旺文社 全訳古語辞典"] span[data-sc-rectr][data-sc-fill] {
  color: #f5f5f5 !important;
}
.nightMode
  [data-dictionary="旺文社 全訳古語辞典"]
  span[data-sc-rectr][data-sc-fill] {
  color: #1e1e1e !important;
}

/* Default Layouts */
html.mobile .sentence, html:not(.mobile) .sentence-alt,
.audio-buttons-alt, .image-alt {
  display: none;
}

/*
 *  USER SETTINGS
 *  Please modify the variables at the top of the file.
 */
/* Layout changes */
#lapis[data-main-picture-position="left"] .def-header {
  flex-flow: row-reverse;
}

#lapis[data-main-picture-position="alt"] .dh-image,
#lapis[data-audio-buttons="alt"] .audio-buttons,
#lapis[data-sentence-position="above"] .sentence-alt,
#lapis[data-sentence-position="below"] .sentence {
  display: none;
}

#lapis[data-main-picture-position="alt"] .image-alt,
#lapis[data-audio-buttons="alt"] .audio-buttons-alt,
#lapis[data-sentence-position="above"] .sentence,
#lapis[data-sentence-position="below"] .sentence-alt {
  display: block;
}

/* Audio Buttons Settings */
#lapis[data-audio-buttons="fixed"] .audio-buttons {
  position: fixed;
  bottom: 0;
  left: 0;
  z-index: 1000;
}

#lapis[data-audio-buttons="header"] .audio-buttons {
  position: static;
}

/* Other Settings */
#lapis[data-sentence-furigana="always"] .sentence rt,
#lapis[data-sentence-furigana="always"] .sentence-alt rt {
  visibility: visible;
}

#lapis[data-sentence-furigana="off"] .sentence rt,
#lapis[data-sentence-furigana="off"] .sentence-alt rt {
  display: none;
}

#lapis[data-nsfw-blur-contained="on"] .NSFW,
#lapis[data-nsfw-blur-contained="on"] .nsfw,
#lapis[data-nsfw-blur-contained="on"] .Nsfw {
  overflow: hidden;
}

#lapis[data-glossary-separator="on"] .definition {
  & li[data-dictionary]:not(:last-of-type),
  & li[data-details]:not(:last-of-type) {
    border-bottom: 1px dashed var(--fg-subtle);
  }
}

#lapis[data-jitendex-format~="minimal"] .definition [data-sc-content]:not([data-sc-content="glossary"]),
#lapis[data-jitendex-format~="no-sentence"] .definition [data-sc-content|="example-sentence"],
#lapis[data-jitendex-format~="no-forms"] .definition [data-sc-content="forms"],
#lapis[data-jitendex-format~="no-xref"] .definition [data-sc-content|="xref"],
#lapis[data-jitendex-format~="no-img"] .definition [data-sc-content|="graphic"] {
  display: none;
}

#lapis[data-jitendex-format~="minimal"] .definition,
#lapis[data-jitendex-format~="no-tags"] .definition {
  & [data-sc-code] {
    display: none;
  }
  & ul {
    padding-inline-start: 0px;
    margin-block: 0px;
    & > li::marker {
      content: "";
    }
  }
}

/* Hibiki delta — see LapisNoteType.fushiCssOverride doc. */
.def-info {
  margin-top: 0.6em;
}

/* BUG-2155：`.tags` 给 `#pitch-tags` 的是 `max-width: 60dvw` —— 一个**视口**相对
   的上限，塞进 `max-width: 820px` 的 .def-header 里毫无意义：宽屏上 60dvw 比整个
   卡头还宽，标签框于是想多宽有多宽。改成相对容器，框永远待在词头这一列里。
   `white-space` 同理：`.tags` 的 nowrap 是给「一个短标签」设计的，音标词典一个词
   能给十几条，挤成一行只能靠 text-overflow 截掉大半。同特异性、后置胜出。 */
#pitch-tags {
  max-width: 100%;
  white-space: normal;
}

/* BUG-2151：`ol` 与 `ul` 一起归一。Lapis 自己的 handlePitches 只在字段里能解析出
   数字/假名声调时才重建 `#pitch-tags`（英语 IPA 两者都没有 → 提前 return），此时
   框里留的是制卡侧原样写入的列表 HTML。存量卡片的字段里存的是 `<ol>`（BUG-2151
   之前 popup.js 的产出），漏掉 `ol` 就等于让这批已经躺在用户 Anki 里、改不了的卡
   继续吃浏览器默认的 `padding-inline-start: 40px` + `margin-block: 1em`：黑框超
   高、左边一大块空白、条目之间还没有分隔符。上游只写了 `ul`，这里补 `ol` 的对偶
   （全新选择器，不与上游冲突）。 */
.pitch ol {
  list-style: none;
  display: inline;
  margin: 0;
  padding: 0;
}

.pitch ol > li {
  display: inline;
}

.pitch ol > li:not(:last-child)::after {
  content: "・";
  color: var(--fg-color);
}

/* BUG-2155：标签框里的列表是 wrap 的 flex 容器，不是 inline 流。
   为什么非得是 flex：制卡侧产出的是 `<li>…</li><li>…</li>`，**元素之间一个空白都
   没有**，而行内流的换行点来自空白 —— 没有空白就没有换行机会，十几条音标只能挤成
   一条撑爆卡头的长行。flex 容器的换行点在 item 边界，不依赖空白，于是既能换行、
   又不会从某条音标中间断开。
   日语那档（1~3 个短标签）一行放得下，wrap 不触发，渲染与原来的 inline 流一致。
   与上游 `#pitch-tags ul{display:inline}` 同特异性、后置胜出。 */
#pitch-tags ul,
#pitch-tags ol {
  list-style: none;
  display: inline-flex;
  flex-wrap: wrap;
  justify-content: center;
  margin: 0;
  padding: 0;
}

/* flex item 内部仍然不许断行：一条音标是一个整体，断成 `[/fɜː` + `st/]` 比换行更糟。 */
#pitch-tags li {
  display: inline;
  white-space: nowrap;
}

#pitch-tags ol > li:not(:last-child)::after {
  content: "・";
  color: var(--bg-color);
  font-size: 0.8em;
}

/* BUG-2155：flex item 的 min-width 默认是 auto，也就是「不小于内容的最小尺寸」。
   音标标签框（#pitch-tags）是个 inline-block，宽度就是它的内容宽，词典给出十几条
   音标时轻松超过整个卡头 —— 于是这一列的最小宽度顶穿 .def-header，右边的
   .dh-image 被压成 0，封面图整个消失。min-width: 0 解开这条约束：本列该让位就让位，
   超出的部分交给 #pitch-tags 自己处理（换行 / 裁切）。
   短音标（日语 [1]・[3]）本来就不顶宽，这行对它们是 no-op。 */
.dh-vocab {
  min-width: 0;
}

