  > li,
li[data-details="JMdict Extra"] .dict-group__glossary > ul > li,
li[data-details="JMdict Extra"]
  .dict-group__glossary
  ul[data-sc-content="glossary"]
  > li {
  display: inline;
  padding-right: 0em;
  margin-right: 0em;
