}

.front-sentence {
  font-size: var(--sentence-font-size);
  display: inline-block;
  line-height: 1.5;
}

#hint {
  font-size: var(--hint-font-size);
  margin-top: -5px;
  line-height: 1.5;
}

#click {
  user-select: none;
}

#click .front-vocab {
  display: inline-block;
  line-height: 1.2;
  margin-bottom: 20px;
  border-bottom: 2px dotted var(--fg-subtle);
}

/* ----- Back elements ----- */

/* Vocab on the back (for mobile) */
.vocab {
  line-height: 1.5;
  font-size: var(--back-vocab-font-size);
}

a {
  color: #3b82f6 !important;
}

.nightMode a {
  color: #93c5fd !important;
}

/* Header */
header {
  color: var(--fg-subtle);
  height: 40px;
  text-align: right;
  width: 100%;
  font-size: 1rem;
}

.top-container {
  font-family: var(--font-sans);
  max-width: calc(var(--max-width) + 20px);
  margin: 0px auto;
  width: calc(100% - 20px);
  fill: var(--fg-subtle) !important;
  position: relative;
  display: inline-block;
}

.freq-dropdown {
  cursor: pointer;
}

.freq-list-container {
  display: none;
  position: absolute;
  top: 100%;
  right: 0;
  background-color: var(--tooltip-hover-color);
  color: var(--fg-color);
  padding: 10px;
  border-radius: 5px;
  z-index: 1000;
  width: 200px;
}

.freq-list-container ul {
  list-style-type: none;
  line-height: 1.5;
  margin: 0;
  padding: 0;
}

.freq-dropdown:hover .freq-list-container {
  display: block;
}

main {
  width: min(var(--max-width), calc(100% - 20px));
  margin-inline: auto;
}

